    @EventHandler( payloadType=AssignBomItemsToBOMEvent.class)
    public void handle( AssignBomItemsToBOMEvent event) {
	    LOGGER.info("handling AssignBomItemsToBOMEvent - " + event );
	    
	    // ------------------------------------------
    	// delegate to addTo 
    	// ------------------------------------------ 
	    BOM entity = addToBomItems(event.getBOMId(), event.getAddTo() );
        
    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindBOM( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllBOM( entity );
    }
    

/*
 * @param	event RemoveBomItemsFromBOMEvent
 */
@EventHandler( payloadType=RemoveBomItemsFromBOMEvent.class)
public void handle( RemoveBomItemsFromBOMEvent event) {
    LOGGER.info("handling RemoveBomItemsFromBOMEvent - " + event );

    BOM entity = removeFromBomItems(event.getBOMId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindBOM( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllBOM( entity );
}



    /**
     * Method to retrieve the BOM via an BOMPrimaryKey.
     * @param 	id Long
     * @return 	BOM
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public BOM handle( FindBOMQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getBOMId() );
    }
    
    /**
     * Method to retrieve a collection of all BOMs
     *
     * @param	query	FindAllBOMQuery 
     * @return 	List<BOM> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<BOM> handle( FindAllBOMQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindBOM,
 * but only if the id matches
 *
 * @param		entity	BOM
 */
	protected void emitFindBOM( BOM entity ) {
		LOGGER.info("handling emitFindBOM" );
		
	    queryUpdateEmitter.emit(FindBOMQuery.class,
	                            query -> query.getFilter().getBOMId().equals(entity.getBOMId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllBOM
	 * 
	 * @param		entity	BOM
	 */
	protected void emitFindAllBOM( BOM entity ) {
		LOGGER.info("handling emitFindAllBOM" );
		
	    queryUpdateEmitter.emit(FindAllBOMQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(BOMProjector.class.getName());

